// === Tab: mySketch ===
let particles = [];
let layers = 3;
let singularity;

function setup() {
  createCanvas(windowWidth, windowHeight);
  colorMode(HSB);
  noStroke();
  for (let l = 0; l < layers; l++) {
    for (let i = 0; i < 600; i++) {
      particles.push(new VortexParticle(l));
    }
  }
  singularity = createVector(width / 2, height / 2);
  background(0);
}

function draw() {
  // Dim background for ghost trails
  fill(0, 0.05);
  rect(0, 0, width, height);

  translate(width / 2, height / 2);

  // Move singularity with slight lag toward mouse
  singularity.lerp(createVector((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))), (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY)))), 0.05);
  let singularityOffset = createVector((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))) - width / 2, (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))) - height / 2).div(200);

  for (let p of particles) {
    p.update(singularityOffset);
    p.show();
  }
}

class VortexParticle {
  constructor(layer) {
    this.layer = layer;
    this.reset();
  }

  reset() {
    this.radius = random(50, width / 2);
    this.angle = random(TWO_PI);
    this.z = random(0.5, 2) + this.layer * 0.4;
    this.hueBase = map(this.layer, 0, layers, 200, 360);
    this.size = map(this.z, 0.5, 3, 0.5, 2);
    this.alpha = random(100, 255);
    this.phase = random(TWO_PI); // for wave jitter
  }

  update(singularityOffset) {
    this.radius -= this.z;
    this.angle += 0.003 * this.z;

    // wave distortion
    this.wave = sin(this.phase + frameCount * 0.05 + this.z) * 10;
    this.phase += 0.005;

    if (this.radius < 10) this.reset();

    // simulate attraction toward mouse-altered singularity
    this.offset = singularityOffset.copy().mult(this.radius * 0.2);
  }

  show() {
    let x = cos(this.angle) * (this.radius + this.wave) + this.offset.x;
    let y = sin(this.angle) * (this.radius + this.wave) + this.offset.y;

    // glow & hue shift
    let h = (this.hueBase + frameCount * 0.5 + this.wave) % 255;
    let alpha = map(this.radius, 10, width / 2, 255, 0);

    fill(h, 200, 255, alpha);
    ellipse(x, y, this.size * 2);
  }
}

